        first start;
        then if phaseIndex == 2 {
          first start;
          then assign led1State := false;
          then assign led2State := false;
          then assign led3State := true;
        } else {
          first start;
          then if phaseIndex == 3 {
            first start;
            then assign led1State := false;
            then assign led2State := false;
            then assign led3State := false;
          } else {
            first start;
            then assign led1State := false;
            then assign led2State := false;
